using HRIS.Api.DTOs.Family; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace HRIS.Api.Controllers; [ApiController][Route("api/family-changes")][Authorize] public class FamilyChangesController:ControllerBase { private readonly IFamilyChangeService _service; public FamilyChangesController(IFamilyChangeService service)=>_service=service; [HttpGet] public async Task<ActionResult<List<FamilyChangeResponseDto>>> Get()=>Ok(await _service.GetAsync(User.ToUserContext())); [HttpPost] public async Task<ActionResult<FamilyChangeResponseDto>> Create(FamilyChangeCreateDto dto)=>Ok(await _service.CreateAsync(dto,User.ToUserContext())); }
